package pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.entities;
import jakarta.persistence.*;
@Entity @Table(name="meters",uniqueConstraints=@UniqueConstraint(name="uq_meters_edge_unique_key",columnNames={"edge_fk","unique_key"})) public class Meters {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer id; @Column(name="edge_fk",nullable=false) private Long edgeFk; @Column(name="unique_key",nullable=false,length=128) private String uniqueKey; @Column(name="name",nullable=false,length=255) private String name; @Column(name="enabled",nullable=false) private boolean enabled; @Column(name="display_order",nullable=false) private int displayOrder;
 protected Meters(){} public Meters(Long edgeFk,String uniqueKey,String name,boolean enabled,int displayOrder){this.edgeFk=edgeFk;this.uniqueKey=uniqueKey;this.name=name;this.enabled=enabled;this.displayOrder=displayOrder;} public Integer getId(){return id;} public Long getEdgeFk(){return edgeFk;} public String getUniqueKey(){return uniqueKey;} public String getName(){return name;} public boolean isEnabled(){return enabled;} public int getDisplayOrder(){return displayOrder;} public void setEdgeFk(Long v){edgeFk=v;} public void setUniqueKey(String v){uniqueKey=v;} public void setName(String v){name=v;} public void setEnabled(boolean v){enabled=v;} public void setDisplayOrder(int v){displayOrder=v;}
}
